import { ApiProperty } from "@nestjs/swagger";
import { IsNotEmpty, IsString } from "class-validator";

export class oAuthDto {
  @ApiProperty({
    description: 'firebase generated token',
    example: 'eyJhbGciOiJSUzI1NiIsImtpZCI6ImQzMjEwMDJmYjM4ZTE1YjJjNmM2NjJjNzFjYjM4NjZjNzEwNjM4ZTgifQ..YkFjZTEyMjMtNjFjZi00YzRmLWFmMjMtMjFjZTEyMjNjZjE2N2YzOWMxMjM0NTY3ODkw'
  })
  @IsString()
  @IsNotEmpty()
  firebaseToken: string
}